mapper.select:
SELECT COUNT(*) FROM bus_stocktake
WHERE status IN (1, 2)
  AND COALESCE(finish_time, create_time) < #{cutoff}

mapper.insert:
INSERT INTO archive_bus_stocktake
    (id, stocktake_no, status, operator, remark, create_time, finish_time, warehouse_id, archived_at)
SELECT id, stocktake_no, status, operator, remark, create_time, finish_time, warehouse_id, #{archivedAt}
FROM bus_stocktake
WHERE status IN (1, 2)
  AND COALESCE(finish_time, create_time) < #{cutoff}
ORDER BY id
LIMIT #{limit}

mapper.delete:
DELETE FROM bus_stocktake
WHERE id IN (
    SELECT id FROM archive_bus_stocktake WHERE archived_at = #{archivedAt}
)
AND status IN (1, 2)
AND COALESCE(finish_time, create_time) < #{cutoff}
LIMIT #{limit}

mapper.select:
SELECT COUNT(*) FROM bus_stocktake_item
WHERE stocktake_id IN (
    SELECT id FROM bus_stocktake
    WHERE status IN (1, 2)
      AND COALESCE(finish_time, create_time) < #{cutoff}
)

mapper.insert:
INSERT INTO archive_bus_stocktake_item
    (id, stocktake_id, goodsid, system_num, actual_num, diff_num, remark, archived_at)
SELECT i.id, i.stocktake_id, i.goodsid, i.system_num, i.actual_num, i.diff_num, i.remark, #{archivedAt}
FROM bus_stocktake_item i
INNER JOIN archive_bus_stocktake a ON a.id = i.stocktake_id
WHERE a.archived_at = #{archivedAt}
ORDER BY i.id
LIMIT #{limit}

mapper.delete:
DELETE FROM bus_stocktake_item
WHERE id IN (
    SELECT id FROM archive_bus_stocktake_item WHERE archived_at = #{archivedAt}
)
LIMIT #{limit}

